    private final A a;
    private final B b;

    public Pair(A a, B b) {
        this.a = Objects.requireNonNull(a);
        this.b = Objects.requireNonNull(b);
    }

    public A getA() {
        return a;
    }

    public B getB() {
        return b;
    }

    @Override
    public boolean equals(Object o) {
        if (this == o) {
            return true;
        } else if (o instanceof Pair<?,?>) {
            Pair<?,?> other = (Pair<?,?>) o;
            return Objects.equals(getA(), other.getA()) && Objects.equals(getB(), other.getB());
        }
        return false;
    }

    @Override
    public int hashCode() {
        int result = Objects.hashCode(getA());
        result = 31 * result + Objects.hashCode(getB());
        return result;
    }

    @Override
    public String toString() {
        return String.format("Pair(%s, %s)", getA(), getB());
    }
}
