package be.kuleuven.cs.smartdoc.helpers;

import java.io.File;
import java.util.List;

import com.google.common.collect.Lists;

public class FileHelper {
	
	public static List<File> find(File startDirectory, String extension) {
		List<File> files = Lists.newArrayList();

		File[] filesInFolder = startDirectory.listFiles();
		if (filesInFolder!= null) {
			for (File file : filesInFolder) {
				if (file.isDirectory()) {
					files.addAll(find(file, extension));
				}
				if (file.getName().endsWith(extension)) {
					files.add(file);
				}
			}
		}
		return files;
	}
}
