class ExerciseController(private val exerciseRepository: ExerciseRepository) {

    @GetMapping(value = ["/{id}"], produces = ["application/json"])
    fun getExerciseById(@PathVariable id: Int): ResponseEntity<Exercise> {
        return ResponseEntity.ok(exerciseRepository.findById(id).orElse(null))
    }

    @GetMapping(value = ["/{id}/input"], produces = ["application/json"])
    fun getExerciseInputById(@PathVariable id: Int): ResponseEntity<Any> {
        return ResponseEntity.ok(ExerciseFactory.getInstance().createInput(id))
    }

    @GetMapping(value = ["/{id}/output"], produces = ["application/json"])
    fun getExerciseOutputById(@PathVariable id: Int): ResponseEntity<Any> {
        return ResponseEntity.ok(ExerciseFactory.getInstance().createOutput(id))
    }

    @GetMapping(value = ["/categories", "/categories/{id}"], produces = ["application/json"])
    fun getAllCategories(@PathVariable id: Int?): ResponseEntity<Iterable<ExerciseCategory>> {
        return if (id == null) {
            ResponseEntity.ok(exerciseRepository.findAllCategories())
        } else {
            ResponseEntity.ok(exerciseRepository.findCategoryById(id))
        }
    }

    @GetMapping(value = ["/categories/{categoryId}/exercises", "/categories/{categoryId}/exercises/{id}"], produces = ["application/json"])
    fun getAllExercisesByCategoryId(@PathVariable categoryId: Int, @PathVariable id: Int?): ResponseEntity<Iterable<Exercise>> {
        return if (id == null) {
            ResponseEntity.ok(exerciseRepository.findExercisesByCategoryId(categoryId))
        } else {
            ResponseEntity.ok(exerciseRepository.findExerciseById(id))
        }
    }
