public String generateContent(URL url) throws Exception {
        StringBuilder res = new StringBuilder();
        res.append("<html>\n")
               .append("<body>\n")
               .append("  <a href=\"" + url.toExternalForm() + "\">" + url.toExternalForm() + "</a><br>\n");
        res.append("  <pre>\n")
               .append("    " + generateContent(url, res, true));
        res.append("  </pre>\n")
               .append("</body>\n")
               .append("</html>\n");
        return res.toString();
    }

    private String generateContent(URL url, StringBuilder res, boolean first) throws Exception {
        if (!first) {
            res.append("    ");
        }
        if (url.getFile().startsWith("/")) {
            throw new Exception("Cannot fetch root of " + url.toString());
        }
        if (url.getFile().endsWith("/")) {
            res.append("<br>\n");
            for (URL subUrl : url.openConnection().getContentType().split("; ")) {
                res.append("    <a href=\"" + subUrl + "\">" + subUrl.toString() + "</a>\n");
                res.append("    <pre>\n");
                res.append("      " + generateContent(subUrl, res, false));
                res.append("    </pre>\n");
                res.append("    <br>\n");
            }
        }
        res.append(url.toExternalForm());
        return url.openStream().readAllBytes().toString();
    }
}
