import javax.crypto.spec.SecretKeySpec;
import javax.xml.bind.DatatypeConverter;

import io.jsonwebtoken.Claims;
import io.jsonwebtoken.Jwts;
import io.jsonwebtoken.SignatureAlgorithm;

public class JwtGenerator {
	public static String generateJwtToken(String usuario, String senha, Map<String, String> params) {
		Map<String, Object> claims = new HashMap<>();
		claims.put("idUsuario", usuario);
		claims.put("passUsuario", senha);
		for (String key : params.keySet())
			claims.put(key, params.get(key));
		String secretKey = DatatypeConverter.printHexBinary(new SecretKeySpec(Config.get().getSecretKey().getBytes(), "HmacSHA256"));
		return Jwts.builder().setClaims(claims).setExpiration(new Date(System.currentTimeMillis() + Config.get().getTokenExpirationTime()))
				.signWith(SignatureAlgorithm.HS256, secretKey).compact();
	}

	public static Map<String, String> decodeJwtToken(String token) {
		try {
			Map<String, Object> claims = Jwts.parser().setSigningKey(Config.get().getSecretKey().getBytes()).parseClaimsJws(token).getBody();
			if (!(claims instanceof Map)) 
				throw new RuntimeException("Invalid JWT signature: " + token);
			Map<String, String> ret = new HashMap<>();
			ret.put("idUsuario", claims.get("idUsuario").toString());
			ret.put("passUsuario", claims.get("passUsuario").toString());
			return ret;
		}catch (Exception e) { e.printStackTrace(); return null; }
	}

	public static String generateNewJwtToken(String idUsuario, String passUsuario) {
		return generateJwtToken(idUsuario, passUsuario, new HashMap<>());
	}

