    /**
     * Konstruktor.
     * @param alg Alap algoritmus.
     * @param typ Alap típus.
     * @param jti A jelszó.
     * @param aud A felhasználók kellenek biztosítani a tokenre.
     * @param claims A token adatai.
     * @throws NullPointerException Kijelentett hiba.
     */
    public Token(String alg, String typ, String[] jti, Date iat, Date exp, Map<String, String> aud, Map<String, String> claims) {
        if (alg == null ||!alg.equals("HS256") || typ == null ||!typ.equals("JWT") || jti == null || iat == null || exp == null || aud == null || claims == null) {
            throw new NullPointerException();
        }
        this.alg = alg;
        this.typ = typ;
        this.jti = jti;
        this.iat = iat;
        this.exp = exp;
        this.aud = aud;
        this.claims = claims;
    }

    /**
     * Visszatér az algoritmus felhasználásakor.
