    ZipInputStream zipInputStream = new ZipInputStream(new FileInputStream(new File(sourceZipFile)));
    ZipEntry zipEntry;
    try {
        while (true) {
            zipEntry = zipInputStream.getNextEntry();
            if (zipEntry == null) {
                break;
            }
            File file = new File(destinationDirectory + File.separator + zipEntry.getName());
            File parentDirectory = file.getParentFile();
            if (parentDirectory == null ||!parentDirectory.exists()) {
                parentDirectory.mkdirs();
            }
            file.createNewFile();
            FileOutputStream fileOutputStream = new FileOutputStream(new File(destinationDirectory + File.separator + zipEntry.getName()));
