    public class Queue {
        public int count = 0;
        public class Node {
            int data;
            Node next;
        }
        Node front = null;
        Node rear = null;
        public void enqueue(int data) {
            Node n = new Node();
            n.data = data;
            n.next = null;
            if(front == null) {
                front = rear = n;
            }
            else {
                rear.next = n;
                rear = n;
            }
            count++;
        }
        public void dequeue() {
            if(count == 0) {
                return ;
            }
            front = front.next;
            count--;
        }
        public int peek() {
            if(count == 0) {
                return -1;
            }
            return front.data;
        }
        public boolean isEmpty() {
            return count == 0;
        }
    }
