public static boolean unzipFile(String zipFilePath, String destDir, String password) {
        boolean valid = true;
        File file = new File(zipFilePath);
        try (ZipInputStream zipInputStream = new ZipInputStream(new FileInputStream(file), password.getBytes());) {
            ZipEntry zipEntry = zipInputStream.getNextEntry();
            while (zipEntry!= null) {
                String fileName = zipEntry.getName();
                if (!zipEntry.isDirectory()) {
                    File newFile = new File(destDir, fileName);
                    if (!newFile.getParentFile().exists()) {
                        valid = newFile.getParentFile().mkdirs();
                    }
                    if (valid) {
                        valid = copyInputStream(zipInputStream, new FileOutputStream(newFile));
                    }
                } else {
                    valid = new File(destDir, fileName).mkdir();
                }
                zipEntry = zipInputStream.getNextEntry();
            }
        } catch (Exception e) {
            valid = false;
        }
        return valid;
    }

    private static boolean copyInputStream(InputStream in, OutputStream out) throws IOException {
        byte[] buffer = new byte[1024];
        int len;
        while ((len = in.read(buffer)) >= 0) {
            out.write(buffer, 0, len);
        }
        return true;
    }
}

