                throw new Exception("Cannot extract file named '" + name + "' because it starts with a dot in zip file '" + zipFile + "'.");
            if(name.startsWith(".."))
                throw new Exception("Cannot extract file named '" + name + "' because it has double dots (dots in zip file '" + zipFile + "').");
