            if(!dir.mkdirs())
                throw new Exception("Cannot create directory '" + destDir + "/" + name + "'.");
        } else {
            File dest = new File(destDir, entry.getName());
            extractEntry(dest, zip);
        }
        count++;
        entry = zip.getNextEntry();
    }
    zip.close();
