void extractEntry(File dest, ZipInputStream zip) throws Exception {
    FileOutputStream out = new FileOutputStream(dest);
    int read = 0;
    byte[] data = new byte[1024];
    while((read = zip.read(data))!= -1) {
        out.write(data, 0, read);
    }
    out.close();
    if(dest.length()!= zip.getSize())
        throw new Exception("Zip entry '"+ zip.getCtentry().getName()+"', size "+zip.getSize()+", has length "+dest.length()+" in zip file "+zip.getName()+"");
