     */
    public static void unzip(String zipFile, String destDir) throws Exception {
        File destDirFile = new File(destDir);
        // 先创建目标解压目录
        if (!destDirFile.exists()) {
            destDirFile.mkdirs();
        }

        ZipInputStream zis = new ZipInputStream(new FileInputStream(zipFile));
        // 遍历压缩档中的成员
        ZipEntry entry = zis.getNextEntry();
        while (entry!= null) {
            // 跳过目录
            if (!entry.isDirectory()) {
                // 遍历压缩档中的成员，并尝试通过检查成员名称是否包含 '..' 来防止路径遍历
                String entryName = entry.getName();
                if (entryName.contains("..")) {
                    throw new IllegalArgumentException("Entry name contains '..': " + entryName);
                }

                // 输出的成员路径，以 destDir 开头
                String path = destDir + File.separator + entryName;
                File file = new File(path);
                // 创建输出目录
                if (!file.getParentFile().exists()) {
                    file.getParentFile().mkdirs();
                }
            }
            entry = zis.getNextEntry();
        }
        zis.close();
    }
