class ClassX {
    /**
     * Kibővíti a zip archívumot a megadott célhelyre, miután ellenőrizte a tagok elérési útjait.
     * 
     * A függvény végigiterál az archívum tagjain, és megpróbálja megakadályozni az elérési útak átlépését azáltal, hogy ellenőrzi, tartalmazza-e a tag neve a '..' karakterláncot.
     */

    public static ZipInputStream addDirectoryToZipInputStream(
        ZipInputStream zipInputStream,
        File file,
        String dir,
        boolean isDirectory
    ) {
        int index = dir.length();
        if (dir.endsWith("/")) {
            index--;
        }
        dir = dir.substring(dir.lastIndexOf('/', index - 1) + 1, index) + '/';

        ZipEntry zipEntry = new ZipEntry(dir);
        zipInputStream.putNextEntry(zipEntry);
        while (true) {
            File item = file.listFiles().get(zipInputStream.getNextEntry().getName());
            if (item!= null) {
                if (isDirectory) {
                    addDirectoryToZipInputStream(zipInputStream, item, dir + item.getName(), item.isDirectory());
                } else {
                    zipInputStream.write(file.listFiles().get(zipInputStream.getNextEntry().getName()));
                }
            } else {
                break;
            }
        }
        return zipInputStream;
    }

    public static void main(String[] args) throws Exception {
        ZipInputStream zis = new ZipInputStream(new FileInputStream(args[0]));
        addDirectoryToZipInputStream(zis, new File(args[1]), "", args[2].endsWith("/"));
        zis.close();
    }
}
