    public static boolean open(String path) {
        Matcher matcher = Pattern.compile("\\\\([\\w\\\\]+)?").matcher(path);
        boolean found = false;

        if (matcher.find()) {
            String extension = matcher.group();

            if (extension.equals(".java")) {
                found = true;
            }
        }

        return found;
    }
