    if (s.startsWith("/")) {
        return extract(s.substring(1), file, path);
    } else {
        if (file!= null) {
            // se non viene trovato il file, il risultato è null.
            if (path.startsWith("/")) {
                return extract(s, file, path.substring(1));
            } else if (path.endsWith("/")) {
