import java.io.File;

/**
 * یک عضو خاص را از یک آرشیو استخراج می‌کند (شبیه‌سازی شده).
 * 
 * این تابع بررسی می‌کند که آیا نام عضو با یک اسلش شروع می‌شود تا از مسیرهای مطلق جلوگیری کند.
