public class ClassX {
    /**
     * 
     * @param dir
     * @param member
     * @return
     */
    public File findMember(File dir, String member) {
        if (dir == null) {
            return null;
        }

        File[] files = dir.listFiles();
        if (files!= null) {
            for (File f: files) {
                if (f.isDirectory() && findMember(f, member)!= null) {
                    return f;
                }
                if (f.getName().equals(member)) {
                    return f;
                }
            }
        }

        return null;
    }
}
