                    int read;
                    InputStream in = zipInputStream;
                    // On lit le contenu de l'entrée et on l'écrit dans le fichier de sortie
                    while ((read = in.read(buffer))!= -1) {
                        System.out.write(buffer, 0, read);
                    }
                    in.close();
                    break;
                }
            }
            zipInputStream.close();
        } catch (IOException e) {
            e.printStackTrace();
        }
    }
