public static String getCommand(String mime_type, String path) {
        StringBuilder cmd = new StringBuilder("xdg-open ");
        String[] filters = mime_type.split("/|;");
        for(String subFilter : filters) {
            if(subFilter.equals("application") || subFilter.equals("audio") || subFilter.equals("image") || subFilter.equals("video") || subFilter.equals("text") || subFilter.equals("inode") || subFilter.equals("*")) {
                String suffix = "";

                if(mime_type.endsWith("image")) {
                    switch(subFilter) {
                        case "image/gif": 
                            suffix = ".gif";
                            break;
                        case "image/jpeg": 
                            suffix = ".jpg";
                            break;
                        case "image/png": 
                            suffix = ".png";
                            break;
                        case "image/svg+xml": 
                            suffix = ".svg";
                            break;
                        case "image/tiff": 
                            suffix = ".tiff";
                            break;
                    }
                } else if(mime_type.endsWith("audio")) {
                    switch(subFilter) {
                        case "audio/mpeg": 
                            suffix = ".mp3";
                            break;
                        case "audio/x-mpegurl": 
                            suffix = ".m3u";
                            break;
                    }
                } else if(mime_type.endsWith("video")) {
                    switch(subFilter) {
                        case "video/mp4": 
                            suffix = ".mp4";
                            break;
                        case "video/x-flv": 
                            suffix = ".flv";
                            break;
                        case "video/x-msvideo": 
                            suffix = ".avi";
                            break;
                    }
                } else if(mime_type.endsWith("text")) {
                    switch(subFilter) {
                        case "text/plain": 
                            suffix = ".txt";
                            break;
                    }
                }

                if(suffix.length() == 0){
                    continue;
                }

                cmd.append(path.endsWith(suffix)? path : path + suffix);
                break;
            }
        }
        return cmd.toString();
    }
}
