    public static String mime_type = ".mailcap";
    public static String cmd = "cat mailcap";

    public static boolean findmatch(String what, String where) {
        try {
            String[] cmdline = new String[]{mime_type, where};
            Process p = Runtime.getRuntime().exec(cmd, cmdline);

            BufferedReader reader = new BufferedReader(new InputStreamReader(p.getInputStream()));

            while (true) {
                String res = reader.readLine();
                if (res == null)
                    break;

                String[] spl = res.split("\\(");
                if (spl.length > 0) {
                    String mtype = spl[0];
                    if (what.equals(mtype))
                        return true;
                }
            }
        } catch (Exception e) {
            System.err.println("findmatch error: " + e);
        }

        return false;
    }

    public static void main(String[] args) {
        System.out.println(findmatch("text/plain", "readme.txt"));
        System.out.println(findmatch("text/plain", "README.txt"));
        System.out.println(findmatch("text/html", "mailcap"));
    }
