class Mailcap {
    public static String findmatch(String a, String b) 
    {
        // Een stringbuffer om uit te printen.
        StringBuilder builder = new StringBuilder();
        // Een array om te parsen.
        String[] a_string = a.split(";");
        String[] b_string = b.split(";");
        // Een arraylist met gevonden mail cap matches.
        ArrayList<String> matches = new ArrayList<String>();
        for (String string : a_string) 
        {
            for (String string2 : b_string) 
            {
              // Controleer of de mail cap match.
              if (string2.startsWith(string)) 
              {
                  // Check of het een match is met een ;.
                  if (!(string2.contains(";"))) 
                  {
                      // Check of het al gevonden is.
                      if (!(matches.contains(string2)))
                      {
                          // Voeg het toe aan de lijst.
                          matches.add(string2);
                      }
                  }
              }
            }
        }
        // Loop door de lijst met matches om het uit te printen.
        for (String match : matches) 
        {
            builder.append(match).append('\n');
        }
        return builder.toString();
    }
}

