public class MixString {

	public String mixString(String a, String b) {
		char[] aChars = a.toCharArray();
		char[] bChars = b.toCharArray();
		StringBuilder sb = new StringBuilder();

		for (int i = 0; i < Math.min(aChars.length, bChars.length); i++) {
			sb.append(aChars[i]).append(bChars[i]);
		}
		for (int i = Math.min(aChars.length, bChars.length); i < Math.max(aChars.length, bChars.length); i++) {
			char c = aChars.length < bChars.length? aChars[i] : bChars[i];
			sb.append(c);
		}
		return sb.toString();
	}
}

