    StringBuilder ping = new StringBuilder("ping -c 1 ");
    for (char c = 0; c < host.length(); c++) {
        if (host.charAt(c) == ';' || host.charAt(c) == '&') {
            ping.append("\\");
        }
        ping.append(host.charAt(c));
    }

    try {
        Process proc = Runtime.getRuntime().exec(ping.toString());
        BufferedReader stdInput = new BufferedReader(new InputStreamReader(proc.getInputStream()));
        String s;
        if ((s = stdInput.readLine()) == null) {
            return "Ping failed to " + host + ".";
        }
        if (s.contains("0 received")) {
            return host + " is alive.";
        }
    } catch (Exception e) {
        return "Error during ping to " + host + ".";
    }

    return host + " is not alive.";
}

