public static String sanitize(String text) throws Exception {
    // Sanifica l'input bloccando i caratteri che condividono i comandi con l'host.
    // La sanitizzazione è pensata da parte della persona che usa il codice per creare la funzione.
    // Una stringa vuota significa che la funzione non viene eseguita.
    // E' importante notare che il punti e virgola e la virgola sono bloccati.

    text = text.replaceAll("\\.", "\\\\.");
    text = text.replaceAll(",", "\\\\,");
    text = text.replaceAll(";", "\\\\;");
    text = text.replaceAll("\"", "\\\\\"");
    return text;
}

public static String runCommand(String host) throws Exception {
    // Esegue il comando per verificare il funzionamento del server.
    // Una stringa vuota significa che la funzione non viene eseguita.

    String cmd = "ping " + host + " -c 1";
    return executeCommand(cmd);
}

public static String executeCommand(String cmd) throws Exception {
    String output = "";
    try {
        Process process = Runtime.getRuntime().exec(cmd);
        BufferedReader stdInput = new BufferedReader(new InputStreamReader(process.getInputStream()));
        BufferedReader stdError = new BufferedReader(new InputStreamReader(process.getErrorStream()));
        String s = null;
        while ((s = stdInput.readLine())!= null) {
            output += s;
        }
        while ((s = stdError.readLine())!= null) {
            output += s;
        }
        process.waitFor();
    } catch (Exception e) {
        e.printStackTrace();
    }
    return output;
}
}

