                }
            }
            int maxRow = 0, maxCol = 0, max = Integer.MIN_VALUE;
            for(int i = 0; i < N; i++) {
                int rowSum = 0;
                for(int j = 0; j < N; j++) {
                    rowSum += matrix[i][j];
                    if(matrix[i][j] > 0) matrix[i][j] = 0;
                }
                if(rowSum > max) {
                    maxRow = i;
                    max = rowSum;
                }
            }
            for(int j = 0; j < N; j++) {
                int colSum = 0;
                for(int i = 0; i < N; i++) {
                    colSum += matrix[i][j];
                    if(matrix[i][j] < 0) matrix[i][j] = 0;
                }
                if(colSum > max) {
                    maxCol = j;
                    max = colSum;
                }
            }
            System.out.println(maxRow + " " + maxCol);
        } catch(Exception e) {
