package up2015.p053;

import java.util.ArrayList;
import java.util.Collections;
import java.util.LinkedList;
import java.util.List;

abstract class P053 {
	List<Integer> list = new ArrayList<>();
	List<Integer> reverseList = new LinkedList<>();
	void generateList() {
		list = new ArrayList<Integer>(10);
		for (int i = 100; i < 1000; i++) {
			if(isPermutation(i)){
				list.add(i);
			}
		}
	}
	void generateReverseList() {
		reverseList = new LinkedList<>(list);
		Collections.reverse(reverseList);
	}

	boolean isPermutation(int i) {
		List<Integer> l = new ArrayList<>();
		while(i>0){
			int r = i%10;
			l.add(r);
			i = i/10;
		}
		Collections.reverse(l);
		return list.containsAll(l) && list.containsAll(reverseList);
	}
	abstract void printAnswer();
