import org.tudelft.i5.unit.assignment.java.utils.MockingSudokuController;

import java.util.Scanner;

/**
 * Main class for the MockingSudoku assignment.
 *
 * @author 
 */
public class MockingSudoku {

    /**
     * Default main method to run the MockingSudoku assignment.
     *
     * @param args The args from the command line.
     */
    public static void main(String[] args) {

        MockingSudokuUI ui = new MockingSudokuUI();
        MockingSudokuController controller = new MockingSudokuController(ui);

        Scanner scanner = new Scanner(System.in);
        ui.print("Enter the size of your board: ");
        int dimension = scanner.nextInt();

        ui.print("\nEnter the positions of the cells with the value 0: ");
        int[][] sudoku = new int[dimension][dimension];
        for (int row = 0; row < dimension; row++) {
            for (int col = 0; col < dimension; col++) {
                sudoku[row][col] = scanner.nextInt();
            }
        }

        ui.print("\nEnter the positions of the cells to be solved: ");
        int[][] board = new int[dimension][dimension];
        for (int row = 0; row < dimension; row++) {
            for (int col = 0; col < dimension; col++) {
                board[row][col] = scanner.nextInt();
            }
        }

        controller.setSudoku(sudoku);
        controller.setCellsToSolve(board);

        scanner.close();

        ui.showSudoku(controller.getSudoku());
        controller.solveSudoku();

        ui.clearScreen();
        ui.showSudoku(controller.getSudoku());
    }
}
