            }
            if (j == values.length) {
                throw new RuntimeException("Program buggy!");
            }
            values[ind] = values[j];
            values[j] = values[i];
            i--;
        }
        int lastIdx = 0;
        for (int i=0;i<values.length;i++) {
            if (values[i]!= values[lastIdx]) {
                lastIdx++;
                values[lastIdx] = values[i];
            }
        }
        while (lastIdx < values.length - 1) {
            values[lastIdx] = 0;
            lastIdx++;
        }
        return values;
    }

