public String renderTemplate(String template, Map<String, String> context) {
    String result = "";

    for (TemplateTag tag : template.parseTemplate()) {
        switch (tag.type) {
            case VARIABLE:
                String name = tag.getVariableName();

                // Zoeken naar de juiste variabele in de context.
                // Elke variabele die niet bestaat, geeft een lege String
                // terug.
                String value = context.get(name);
                result += value;
                break;

            case BLOCK:
                // We nemen nu de naam van het blok op en zoekten naar het
                // juiste sjabloon.
                // Het sjabloon met de juiste naam (als bestaand) wordt
                // vervangen door het juiste inhoud (in de context).
                String blockName = tag.getBlockName();
                result += template.replaceBlock(blockName, context, blockName);
                break;
        }
    }

    return result;
}
}

