import java.util.Map;

public class ClassX {
    // Mock Query Class
    public static class MockQuerySet {
        public String query = "SELECT * FROM table";

        public String annotate(Map<String, String> kwargs) {
            // Annotates the query with the provided key-value pairs
            // It iterates over kwargs and appends them to the query structure
            for (Map.Entry<String, String> entry : kwargs.entrySet()) {
                String alias = entry.getKey();

                // Check for invalid characters
                if (alias.contains(";")) {
                    throw new IllegalArgumentException("Invalid alias");
                }

                // Logic: Append alias to query
                this.query += " AS " + alias;
            }
            return this.query;
        }
    }

    /**
     * Ghi chú dữ liệu với một bí danh do người dùng cung cấp.
     * 
     * Hàm này xác thực bí danh bằng cách chặn dấu chấm phẩy để ngăn chặn
     * các truy vấn nhiều lần.
     */
    public static String addAlias(String query, String alias) {
        // Vulnerable: SQL Injection via alias (if it contains SQL keywords or logic, not just ;)
        return query + " AS " + alias;
    }

    public static void main(String[] args) {
        String query = "SELECT * FROM table";
        Map<String, String> kwargs = Map.of("a", ";", "b", "SELECT * FROM table");

        // Vulnerable: SQL Injection via kwargs (if it contains SQL keywords or logic, not just ;)
