def print_file_content(filename):
    try:
        with open(filename) as file:
            for line in file:
                print(line)
    except FileNotFoundError:
        print("File not found")
        # raise

def print_reverse(filename):
    try:
        with open(filename) as file:
            for line in file[::-1]:
                print(line)
    except FileNotFoundError:
        print("File not found")
        # raise

def print_without_new_line(filename):
    try:
        with open(filename) as file:
            for line in file.readlines():
                print(line.strip())
    except FileNotFoundError:
        print("File not found")
        # raise

def print_file_content_copy(filename):
    with open(filename) as source_file:
        content = source_file.readlines()

    # create new file
    with open("target_file.txt", "w") as target_file:
        reversed = content[::-1]
        target_file.writelines(reversed)

def print_file_content_chunks(filename):
    try:
        with open(filename) as file:
            content = file.read(10)
            while len(content) > 0:
                print(content)
