package com.github.nayankumar.kodluyoruz.utils;

import java.io.BufferedReader;
import java.io.File;
import java.io.FileReader;
import java.io.IOException;
import java.nio.file.Path;

/**
 *
 * @author  <>
 */
public class CodeRunner {

    public static void run(Path sourceCodePath, String testClassName, String inputFilesDir) throws Exception {
        File file = sourceCodePath.toFile();
        String className = file.getName().replace(".java", "");
        Path tempFilePath = Common.createTempFile(className);

        if (Common.isEmptyFile(tempFilePath)) {
            Common.writeToFile(tempFilePath, file.getAbsolutePath());
        }
        if (Common.isEmptyFile(tempFilePath)) {
            throw new Exception("Source code has not been compiled successfully. Please check the compilation error messages.");
        }

        try {
            Runtime.getRuntime().exec(new String[]{"javac", tempFilePath.toString()});
            Class<?> cls = Class.forName(className);
            Object instance = cls.newInstance();
            BufferedReader br = Common.getReaderForTestData(inputFilesDir);
            String line;
            while ((line = br.readLine())!= null) {
                String[] arr = line.split("###");
                if (arr.length!= 2) {
                    continue;
                }
                try {
                    Object result = cls.getDeclaredMethod(testClassName, File.class, String.class).invoke(instance, Common.getReaderForTestData(inputFilesDir), arr[0]);
                    if (!arr[1].equals(result.toString())) {
                        System.out.println();
                        System.out.println(arr[0]);
                        System.out.println(arr[1]);
                        System.out.println(result.toString());
                    }
                } catch (Exception e) {
                    e.printStackTrace();
                }
            }
        } finally {
            Common.deleteFile(tempFilePath);
        }
    }
}
