public class Solution {
    public <T, R> List<R> map(List<T> input, Function<T, R> function) {
        List<R> output = new ArrayList<>();
        for (T t : input) {
            output.add(function.apply(t));
        }
        return output;
    }

    public <T, R> List<R> map2(List<T> input, BiFunction<Integer, T, R> function) {
        List<R> output = new ArrayList<>();
        for (int i = 0; i < input.size(); i++) {
            output.add(function.apply(i, input.get(i)));
        }
        return output;
    }
