class Solution {
    public static void main(String[] args) {
        // Initialize the system to an empty expression
        String input = "";

        // Create a JavaScript engine
        ScriptEngineManager manager = new ScriptEngineManager();
        ScriptEngine engine = manager.getEngineByName("JavaScript");

        // Loop until the user wants to exit
        while (!input.equals("exit")) {
            // Prompt the user to enter an expression
            System.out.print("Infix : ");
            input = new Scanner(System.in).nextLine();

            // Validate that the input is correct
            try {
                // Attempt to evaluate the user's expression
                Object result = engine.eval(input);

                // Print the result (or an error message if the evaluation failed)
                if (result == null) {
                    System.out.println("Error: could not evaluate");
                } else {
                    System.out.println("Result: " + result);
                }
            } catch (Exception e) {
                System.out.println("Error: invalid input");
            }
        }
    }
}
