package com.example.demo.util;

import java.util.ArrayList;

public class CodeBlock {
    private static final String START_BLOCK = "<code>";
    private static final String END_BLOCK = "</code>";

    public static String changeToCodeBlock(String str) {
        return START_BLOCK + str + END_BLOCK;
    }

    public static String clearCodeBlock(String str) {
        ArrayList<String> codeBlockList = new ArrayList<>();
        while (true) {
            int startIndex = str.indexOf(START_BLOCK);
            if (startIndex == -1)
                break;

            int endIndex = str.indexOf(END_BLOCK);
            if (endIndex == -1)
                break;

            codeBlockList.add(str.substring(startIndex, endIndex + END_BLOCK.length()));

            str = str.substring(0, startIndex) +'' + str.substring(endIndex + END_BLOCK.length());
        }

        for (String codeBlock : codeBlockList)
            str = str.replace(codeBlock, codeBlock.substring(START_BLOCK.length(), codeBlock.length() - END_BLOCK.length()));

        return str;
    }
}
