                                 2,  1};  // the primes (operators)
    std::vector<int> operands;               // the numbers (operands)

    /**
     * Solve the given number.
     * 
     * The number is given as a string of characters. The digits of the number
     * must be between 0-9, and the operators must be between 0-9 (representing
     * the number of operands).
     * 
     * This function solves the given number and return the result as a string.
     */
    std::string solve(std::string number) {
        // for each operator, we check which is the best operand for it
        // and sum the best operand that we find times the number of operands
        // for each operator
        for (auto o : this->operators) {
            int number_of_operands = number.size() / o;
            for (auto i = 0; i < number_of_operands; ++i) {
                int operand = 0;
                for (auto j = 0; i + j < number_of_operands; ++j) {
                    operand = operand * 10 + number[i + j] - '0';
                }
                this->operands.push_back(operand);
            }
        }

        std::string result = std::to_string(this->operands[0]);
        for (auto i = 1; i < operands.size(); ++i) {
            result += this->operators[i];
            result += std::to_string(this->operands[i]);
        }

        return result;
    }
};
