class Solution {
    public boolean solution(int[] num, int target) {
        boolean result = false;
        int count = 0;
        for (int i = 0; i < num.length; i++) {
            count++;
            if (num[i] == target) {
                result = true;
                break;
            }
            for (int j = 0; j < num.length; j++) {
                if (count == j) continue;
                if ((num[i] + num[j]) == target) {
                    result = true;
                    break;
                }
            }
            if (result) break;
        }
        return result;
    }
}
