public class B {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = Integer.parseInt(sc.nextLine());
        int[] arr = new int[n];
        String[] str = sc.nextLine().split(" ");
        for (int i = 0; i < n; i++) {
            arr[i] = Integer.parseInt(str[i]);
        }
        int[] res = new int[n];
        res[0] = n;
        for (int i = 1; i < n; i++) {
            res[i] = Math.min(res[i - 1], arr[i - 1]) - 1;
        }
        int[] res2 = new int[n];
        res2[n - 1] = n;
        for (int i = n - 2; i >= 0; i--) {
            res2[i] = Math.min(res2[i + 1], arr[i + 1]) - 1;
        }
        long ans = 0;
        for (int i = 0; i < n; i++) {
            ans += Math.min(res[i], res2[i]) * arr[i];
        }
        System.out.println(ans);
    }
}
