public class Sanitizer {
    static final String SCRIPT_REGEX = "<script\\b[^<]*(?:(?!<\\/script>)<[^<]*)*?\\/<\\s*script\\s*>";
    static final Pattern PATTERN = Pattern.compile(SCRIPT_REGEX, Pattern.CASE_INSENSITIVE);

    /**
     * Sanitizes user input by removing script tags.
     * 
     * The function uses string replacement to strip out <script> tags.
     */
    public static String sanitize(String input) {
        return PATTERN.matcher(input).replaceAll("");
    }

