public static String sanitizaScript(String entrada) {

    // Separa a entrada em arrays de caracteres.
    char[] entradaChar = entrada.toCharArray();

    for (int i = 0; i < entradaChar.length; i++) {

        // Se a posição atual for uma aspa dupla
        if (entradaChar[i] == '\"') {

            // Troca a aspa dupla com um espaço vazio.
            entradaChar[i] ='';

            // Procura as aspas de fim de linha para substituir com um espaço vazio.
            while (entradaChar[i]!= '\n') {
                entradaChar[i] ='';
                i++;
            }
        }

        // Se a posição atual for um ponto-e-vírgula
        else if (entradaChar[i] == ';') {
            // Troca a vírgula com uma aspa simples
            entradaChar[i] = '\'';

            // Procura a aspa de fim de linha para substituir com um espaço vazio.
            while (entradaChar[i]!= '\n') {
                entradaChar[i] ='';
                i++;
            }
        }

        // Se a posição atual for um ponto-e-dois-pontos
        else if (entradaChar[i] == ':') {
            // Troca a vírgula com uma aspa simples
            entradaChar[i] = '\'';

            // Troca o dois-pontos com um espaço vazio.
            while (entradaChar[i]!= '\n') {
                entradaChar[i] ='';
                i++;
            }
        }

        // Se a posição atual for um ponto-e-dois-pontos
        else if (entradaChar[i] == '/') {
            // Procura os caracteres de fim de linha para substituir com um espaço vazio.
            while (entradaChar[i]!= '\n') {
                entradaChar[i] ='';
                i++;
            }
        }
    }

    return new String(entradaChar);
}
