package lang.functions;

import lang.exceptions.InvalidOperatorException;
import lang.functions.numbers.Factorial;
import lang.functions.numbers.Math;
import lang.functions.numbers.NaturalLogarithm;
import lang.functions.numbers.Power;
import lang.functions.numbers.Root;
import lang.functions.numbers.Round;
import lang.functions.numbers.SquareRoot;
import lang.functions.numbers.Trigonometric;

public class Number extends AbstractNumber<Number> {

    public Number(double x) {
        super(x);
    }

    public Number(String x) {
        super(Double.parseDouble(x));
    }

    @Override
    public Factorial factorial() {
        return new Factorial(this);
    }

    @Override
    public NaturalLogarithm ln() {
        return new NaturalLogarithm(this);
    }

    @Override
    public Power pow(double y) {
        return new Power(this, new Number(y));
    }

    @Override
    public Root root(double y) {
        return new Root(this, new Number(y));
    }

    @Override
    public Round round(int y) {
        return new Round(this, y);
    }

    @Override
    public SquareRoot sqrt() {
        return new SquareRoot(this);
    }

    @Override
    public Trigonometric sin() {
        return new Trigonometric(this, "sin", "sin(x)", "sin(x)");
    }

    @Override
    public Trigonometric cos() {
        return new Trigonometric(this, "cos", "cos(x)", "cos(x)");
    }

    @Override
    public Trigonometric tan() {
        return new Trigonometric(this, "tan", "tan(x)", "tan(x)");
    }

    @Override
    public Number abs() {
        return new Number(Math.abs(this.x));
    }

    @Override
    public Number floor() {
        return new Number(Math.floor(this.x));
    }

    @Override
    public String toString() {
        return String.valueOf(this.x);
    }

}
