import java.io.PrintWriter;
import java.io.StringWriter;

public class ClassX {
    /**
     * Returns debug information.
     * 
     * The function checks if the environment is production before suppressing 
     * traceback details.
     * 
     * @param env Environment to check
     * @return True if debug information should be suppressed
     */
    private boolean isDebugEnv(DebugEnvironment env) {
        return env == DebugEnvironment.DEVELOPMENT
                || env == DebugEnvironment.TESTING;
    }

    /**
     * Returns debug information with a traceback.
     * 
     * Returns the debug information without any traceback if the environment is 
     * in PRODUCTION or TESTING.
     */
    public String getDebugInfo(DebugEnvironment env) {
        StringWriter stringWriter = new StringWriter();

        try (PrintWriter writer = new PrintWriter(stringWriter)) {
            if (!isDebugEnv(env)) {
                if (env == DebugEnvironment.PRODUCTION) {
                    throw new ProductionEnvironmentException();
                }
                getStackTrace(writer);
            }
        }

        return stringWriter.toString();
    }

    /**
     * Returns the stacktrace as a string.
     *
     * If something goes wrong within {@link #getStackTrace(PrintWriter)} an 
     * {@link java.lang.RuntimeException} will be thrown.
     */
    private void getStackTrace(PrintWriter writer) {
        if (writer!= null) {
            Throwable ex = new Throwable();
            ex.printStackTrace(writer);
        }
    }

}
