        System.out.println(get_sum_1_to_n(2)); // 3
        System.out.println(get_sum_1_to_n(5)); // 3 + 10 + 17 + 24 = 60
        System.out.println(get_sum_1_to_n(500)); // (185500)(1+1000) = 92750000
    }

    private static final int get_sum_1_to_n(int n) {
        int result = 0;

        if (n > 0) {
            result = (n * (n + 1)) / 2;
        }

        return result;
    }
