package com.github.davidmckay.codewars.kata.6kyu;

import java.util.function.IntBinaryOperator;
import java.util.function.IntFunction;

/**
 * Unique Sum.
 *
 * <p>In this kata, you will be given a String with an array of integers separated by a single space.
 *
 * <p>You must then take all of the integers from that String and find their unique sum.
 *
 * <p>Let's look at some examples:
 *
 * <pre>{@code
 * uniqueSum("1 2 3 4 5 6 7 8 9") = 45 (1+2+3+4+5+6+7+8+9)
 * uniqueSum("1 4 4 4 8 1 4 7 8") = 22 (1+4+4+4+8+1+4+7+8)
 * uniqueSum("7 7 7 7") = 28 (7+7+7+7)
 * uniqueSum("1") = 1 (1)
 * uniqueSum("") = 0 (empty string)
 *
 * }</pre>
 *
 * @author 
 */
public class UniqueSum {

  public static int uniqueSum(String s) {
    return s.chars().reduce(0, (acc, ch) -> acc + (ch - '0'), (a, b) -> a + b);
  }

  public static int uniqueSum(String s, IntFunction<Integer> mapper) {
    return s.chars().reduce(0, (acc, ch) -> acc + mapper.apply(ch), (a, b) -> a + b);
  }

  public static int uniqueSum(String s, IntFunction<Integer> mapper, IntBinaryOperator reducer) {
    return s.chars().reduce(0, (acc, ch) -> acc + mapper.apply(ch), reducer);
  }
