class Solution {
    public int maxProfit(int[] arr) {
        if (arr == null || arr.length < 2) return 0;
        int max = 0;
        int min = arr[0];
        for (int i = 1; i < arr.length; i++) {
            int diff = arr[i] - min;
            if (diff < 0) {
                min = arr[i];
            } else if (diff > max) {
                max = diff;
            }
        }
        return max;
    }
}
