import { Schema, model, Document } from'mongoose';
import bcrypt from 'bcrypt';
import crypto from 'crypto';
import { SessionData } from '@utils/session';
import Session from './session';

const SALT_ROUNDS = 10;

const UserSchema: Schema = new Schema({
    username: {
        type: String,
        required: [true, 'Username is required'],
        unique: [true, 'Username already exists'],
    },
    passwordHash: {
        type: String,
        required: [true, 'Password hash is required'],
    },
    email: {
        type: String,
        required: [true, 'Email is required'],
        unique: [true, 'Email already exists'],
        match: [
            /^([a-zA-Z0-9_\-\.]+)@([a-zA-Z0-9_\-\.]+)\.([a-zA-Z]{2,5})$/,
            'Please enter a valid email',
        ],
    },
    token: {
        type: String,
        unique: true,
    },
});

/**
 * Password (salt) should be randomly generated and stored in db
 * This method is used to check if the password is correct or not.
 * @param password The password to compare
 * @param correctPassword The correct password
 * @returns True if the password is correct, False otherwise
 */
UserSchema.methods.isPasswordCorrect = function (password: string, correctPassword: string) {
    return bcrypt.compareSync(password, correctPassword);
};

UserSchema.methods.createToken = function () {
