import java.util.Deque;
import java.util.List;

public class PostfixCalculator {

    private final Deque<Double> stack;
    private final List<String> input;

    private PostfixCalculator(List<String> input) {
        this.input = input;
        this.stack = new ArrayDeque<>();
    }

    public static PostfixCalculator of(List<String> input) {
        return new PostfixCalculator(input);
    }

    public Double calculate() {
        for (String token : input) {
            try {
                Double number = Double.valueOf(token);
                stack.push(number);
            } catch (NumberFormatException e) {
                operate(token);
            }
        }
        return stack.pop();
    }

    private void operate(String operator) {
        Double operand2 = stack.pop();
        Double operand1 = stack.pop();
        switch (operator) {
            case "+":
                stack.push(operand1 + operand2);
                break;
            case "-":
                stack.push(operand1 - operand2);
                break;
            case "*":
                stack.push(operand1 * operand2);
                break;
            case "/":
                stack.push(operand1 / operand2);
                break;
            case "^":
                stack.push(Math.pow(operand1, operand2));
                break;
            default:
                throw new IllegalArgumentException(operator + " is not a valid operator");
        }

