            if(index > 0) {
                jwtHeader.put(field.substring(0, index), field.substring(index + 1));
            }
        }

        Map<String, Object> headerMap = new HashMap<>();
        for (Map.Entry<String, String> field : jwtHeader.entrySet()) {
            headerMap.put(field.getKey(), field.getValue());
        }

