        String signatureAlgorithm = headerMap.get("alg").toString();
        String secret = algorithms.get(signatureAlgorithm);
        if (secret == null) {
            throw new Exception("Algorithm " + signatureAlgorithm + " not supported");
        }
        String generatedSignature = JwtManager.generateSignature(jwtParts[1], secret, signatureAlgorithm);
        if (!generatedSignature.equals(signature)) {
            throw new Exception("Invalid signature");
        }

        return Base64.getDecoder().decode(jwtParts[1]).toString();
    }
