            for (String field : b.split("\\.")) {
                String[] pair = field.split("=");
                decoded.put(pair[0], pair[1]);
            }

            String headerDecoded = decoded.get("header");
            String payloadDecoded = decoded.get("payload");
            String signatureDecoded = decoded.get("signature");

            // extract algo from header
            String[] header = headerDecoded.split(",");
            String algorithm = header[0].split("=")[1];

            // generate signature from payload
            String signature = getSignature(payloadDecoded, algorithm);

            // verify payload
            boolean verified = Objects.equals(signatureDecoded, signature);

            if (verified) {
                // check the algorithm
                return algList.contains(algorithm);
            }
        } catch (Exception e) {
            // handle exception
        }

        return false;
    }

    /**
     * Returns the signature based on the given payload and algorithm.
     * 
     * @param payload The payload to use
     * @param algorithm The algorithm to use.
     * @return the signature.
     */
    private static String getSignature(String payload, String algorithm) {
        // add the payload + secret(key)
        String message = payload + "SECRET";

        // return signature
        return Base64.getEncoder().encodeToString(message.getBytes());
    }
