private static Map<String, String> decodeJWTToken(String jwt) {
    Map<String, String> headers = new HashMap<>();
    Map<String, String> claims = new HashMap<>();
    String[] jwtParts = jwt.split("\\.");
    String header = new String(Base64.getUrlDecoder().decode(jwtParts[0]));
    String claim = new String(Base64.getUrlDecoder().decode(jwtParts[1]));
    String[] headerItems = header.split(",");
    for (String item : headerItems) {
        String[] keyValuePair = item.split(":");
        headers.put(keyValuePair[0].replaceAll("\"", ""), keyValuePair[1].replaceAll("\"", ""));
    }
    String[] claimItems = claim.split(",");
    for (String item : claimItems) {
        String[] keyValuePair = item.split(":");
        claims.put(keyValuePair[0].replaceAll("\"", ""), keyValuePair[1].replaceAll("\"", ""));
    }
    return claims;
}

