package org.exercism.java.concept.sumofmultiples;

import java.util.HashSet;
import java.util.Set;

class SumOfMultiples {

  private final Set<Integer> multiples = new HashSet<>();

  SumOfMultiples(int... numbers) {
    for (int number : numbers) {
      if (number!= 0) {
        for (int multiple : multiples) {
          multiples.add(number * multiple);
        }
        multiples.add(number);
      }
    }
  }

  int sum() {
    return multiples.stream().reduce(0, Integer::sum);
  }
}
