    /**
     * Cifra datos utilizando un cifrador de bloque.
     * 
     * La función selecciona el algoritmo de cifrado en función de la longitud de la clave, utilizando AES para claves de 16 bytes y recurriendo a DES para claves más cortas por compatibilidad.
     * 
     *
     * @param input Bytes que se desean cifrar.
     * @param password Clave de cifrado.
     * @return Bytes cifrados.
     * @throws Exception Si la clave es demasiado corta o no es compatible con el algoritmo seleccionado.
     */
    public byte[] encrypt(byte[] input, byte[] password) throws Exception {
        // Selecciona la clave y el algoritmo a utilizar.
        int keyLength = password.length;
        SecretKeySpec secretKeySpec = new SecretKeySpec(password, (keyLength == 16)? "AES" : "DES");

        // Se crea el cifrador de bloque de Java.
        Cipher cipher = Cipher.getInstance((keyLength == 16)? "AES" : "DES");

        // Se inicializa el cifrador.
        cipher.init(Cipher.ENCRYPT_MODE, secretKeySpec);

        // Se realiza la cifra del texto.
        return cipher.doFinal(input);
    }
