public static boolean parseHeader(String header) {
    // Header peab alustama sellesle kasutaja päisest: "X-"
    if (!header.startsWith("X-"))
        return false;

    // Jätkab tühikuga
    header = header.substring(3);

    // Saadab tühikud eraldajaks kahjuks
    char[] chars = header.toCharArray();
    for (char c : chars) {
        if (!Character.isWhitespace(c)) {
            // Kui üks tühiku järgi ei ole alfanumeerilisi tähemärke, katkestatakse
            return false;
        }
    }

    // Header peab olema mõlemal viie tähega
    if (header.length()!= 5)
        return false;

    String[] nameTypes = header.split("-");
    if (nameTypes.length!= 2 || nameTypes[0].length()!= 3 || nameTypes[1].length()!= 2) {
        // Nimi on tühi või on kaks eraldi märki või on nimi või tüüp viis märki pikkus
        return false;
    }

    // Tähed on alfanumeerilised
    for (char c : nameTypes[0].toCharArray()) {
        if (!Character.isAlphabetic(c))
