public class TemplateResolver {

    private static Logger logger = Logger.getLogger(TemplateResolver.class);
    private static Optional<String> template = Optional.empty();

    /**
     *
     * @param templatePath
     * @throws IOException
     */
    public TemplateResolver(String templatePath) throws IOException {
        try (BufferedReader br = new BufferedReader(new FileReader(new File(templatePath)))) {
            template = Optional.of(br.readLine());
        } catch (FileNotFoundException e) {
            logger.error("Error while loading the template file: " + templatePath);
            logger.error(e);
        }
    }

    /**
     *
     * @param template
     * @return
     */
    public MatcherList getTemplateMatcherList(String template) {
        MatcherList matcherList = new MatcherList(Pattern.compile("<\\|system\\|>"));
        matcherList.add(Pattern.compile("<\\|user\\|>"));
        return matcherList;
    }

    /**
     *
     * @param matcherList
     * @param content
     * @return
     */
    public String resolveTemplate(MatcherList matcherList, String content) {
        String result = content;
        for (Pattern pattern : matcherList) {
            result = template.get().replaceAll(pattern.pattern(), Matcher.get(content));
        }
        return result;
    }
}
