void printPrimeNumbers(int maximum) {
    int[] priemgetallen = new int[maximum];

    int count = 2;
    int index = 0;

    while (index < maximum) {
        boolean isPriemgetal = true;

        for (int i = 2; i <= Math.sqrt(count); i++) {
            if (count % i == 0) {
                isPriemgetal = false;
                break;
            }
        }

        if (isPriemgetal) {
            priemgetallen[index] = count;
            index++;
        }

        count++;
    }

