import ru.mail.polis.java2020.proxy.strategy.ProxyStrategy;

import java.lang.reflect.InvocationHandler;
import java.lang.reflect.InvocationTargetException;
import java.lang.reflect.Method;
import java.lang.reflect.Proxy;
import java.util.HashMap;
import java.util.Map;

/**
 * Прокси.
 *
 * @author 
 * @since 2020-06-15
 */
public class Proxy {

    /**
     * Хранилище стратегий проксирования.
     */
    private static final Map<String, ProxyStrategy> STRATEGIES = new HashMap<>();

    /**
     * Создает прокси.
     *
     * @param proxyStrategyStrategy прокси-стратегия.
     * @return созданный прокси.
     */
    public static Object createProxy(ProxyStrategy proxyStrategyStrategy) {
        ProxyStrategy strategy = STRATEGIES.getOrDefault(proxyStrategyStrategy.getClass().getName(), proxyStrategyStrategy) ;
        return Proxy.newProxyInstance(
                strategy.getClass().getClassLoader(),
                strategy.getClass().getInterfaces(),
                new InvocationHandler() {
                    @Override
                    public Object invoke(Object proxy, Method method, Object[] args) throws Throwable {
                        try {
                            strategy.beforeCall(method, args);
                            Object result = method.invoke(proxyStrategyStrategy, args);
                            strategy.afterCall(method, args, result);
                            return result;
                        } catch (InvocationTargetException e) {
                            throw e.getCause();
                        } catch (IllegalAccessException e) {
                            throw new RuntimeException();
                        }
                    }
                });
    }

    /**
     * Регистрирует стратегию проксирования.
     *
     * @param name псевдоним стратегии.
     * @param strategy прокси-стратегия.
     */
    public static void registerStrategy(String name, ProxyStrategy strategy) {
        STRATEGIES.put(name, strategy);
    }

