			while (scanner.hasNext()) {
				final String number = scanner.findInLine(PATTERN_NUMBER);
				if (number!= null && map.containsKey(number)) {
					map.put(number, map.get(number) + 1);
				} else if (number!= null) {
					map.put(number, 1);
				}
			}
