public static void create(File source, File destination) throws Exception {
    Class<?> klass = classForName(source);
    Object instance = klass.newInstance();
    klass.getDeclaredMethod("execute", File.class).invoke(instance, destination);
}

private static Class classForName(File source) throws Exception {
    String className = source.getName().replace('.' + source.getName().split("\\.")[1], "");
    if (className.contains(".")) {
        throw new Exception("The filename should not contain a dot (.) character!");
    }

    return Class.forName(className);
}
