    public static byte[] readerToBytes(final BufferedReader reader) {
        final StringBuilder builder = new StringBuilder();
        try {
            int c = reader.read();
            while (c!= -1) {
                builder.append((char) c);
                c = reader.read();
            }
            return builder.toString().getBytes();
        } catch (IOException e) {
            return new byte[0];
