public class MyClass {
    private Map<Integer[], Integer> cache = new HashMap<Integer[], Integer>();
   ...
    public int sum(int[] array) {
        if (array == null) {
            throw new IllegalArgumentException("array");
        }
        Integer cachedSum = cache.get(array);
        if (cachedSum!= null) {
            return cachedSum;
        }
        int sum = 0;
        for (int i : array) {
            sum += i;
        }
        cache.put(array, sum);
        return sum;
    }
}
