public static void main(String[] args) {
    if (args.length < 1) {
        System.out.println("usage: java -jar ClassX.jar <yaml-file>");
        return;
    }


    // Laad de YAML-file in een hashmap:
    Yaml yaml = new Yaml(new Constructor(Map.class));
    Map<String, Object> map = yaml.load(new FileReader(args[0]));

    if (map == null || map.size() < 1) {
        System.out.println("input file could not be loaded.");
        return;
    }

    // Laat zien hoe de YAML-file in de hashmap wordt opgeslagen:
    System.out.println("hashmap:");
    for(Map.Entry<String, Object> e : map.entrySet()) {
        System.out.println(e.getKey() + " -> " + e.getValue());
    }

    // Laat zien of het expliciet gevaarlijke objectinstantiatietags gebruikt zijn:
    System.out.println("found dangerous object instantiation tags:");
    for(Map.Entry<String, Object> e : map.entrySet()) {
        if (e.getValue() instanceof Class && ((Class) e.getValue()).getName().startsWith("org.yaml.snakeyaml.constructor")) {
            System.out.println(e.getKey());
        }
    }
}
}

