int main(void) {
	ios_base::sync_with_stdio(false);
	cin.tie(NULL);

	int n;
	cin >> n;

	int arr[n];
	for (int i = 0; i < n; i++) {
		cin >> arr[i];
	}

	// compute the left and right prefix sums
	int l[n], r[n];
	l[0] = 0;
	for (int i = 1; i < n; i++) {
		l[i] = l[i - 1] + arr[i - 1];
	}
	r[n - 1] = 0;
	for (int i = n - 1; i >= 1; i--) {
		r[i - 1] = r[i] + arr[i];
	}

	// for each index i, check if (i == 0) or (i == n - 1) or (l[i] + r[i] == 0)
	int ans = 0;
	for (int i = 0; i < n; i++) {
		if (i == 0 || i == n - 1 || l[i] + r[i] == 0) {
			ans++;
			continue;
		}
		// get the index m such that r[m] - l[m] == 0
		for (int j = i + 1; j <= n - 1; j++) {
			if (r[j] - l[j] == 0) {
				ans++;
				break;
			}
		}
	}

	cout << ans << endl;

	return 0;
}
