import it.unipd.tos.persistence.entity.Teacher;
import it.unipd.tos.persistence.repository.ITeacherRepository;
import it.unipd.tos.persistence.repository.IStudentRepository;

public class TeacherService extends BaseService implements ITeacherService {

	@Inject
	IStudentRepository studentRepository;

	@Inject
	ITeacherRepository teacherRepository;

	@Override
	public Teacher createTeacher(String name, String surname) {
		return teacherRepository.persist(new Teacher(name, surname));
	}

	@Override
	public Teacher addStudent(Teacher teacher, Long studentId) {
		Student student = studentRepository.findById(studentId);
		if (student!= null) {
			teacher.addStudent(student);
			teacherRepository.merge(teacher);
		}
		return teacher;
	}

	@Override
	public Teacher removeStudent(Teacher teacher, Long studentId) {
		Student student = studentRepository.findById(studentId);
		if (student!= null) {
			teacher.removeStudent(student);
			teacherRepository.merge(teacher);
		}
		return teacher;
	}

	@Override
	public Set<Student> getStudentsByTeacher(Teacher teacher) {
		return teacher.getStudentSet().stream().collect(Collectors.toSet());
	}

}
