     */
    public void handle(HttpServletResponse response) {
        String[] badSites = { "www.badsite.com", "www.crapsite.com", "www.badhost.com", "www.evilsite.com",
            "www.badsite.com", "www.crapsite.com", "www.badhost.com", "www.evilsite.com" };

        String url = response.getServletPath();

        // Ανάκτηση της διεύθυνσης του URL
        int hostStart = url.indexOf("http://") + 7;
        int hostEnd = url.indexOf("/", hostStart);

        String host = url.substring(hostStart, hostEnd);

        // Απομακρύνουμε την μαύρη λίστα
        for (String badSite : badSites) {
            if (host.equals(badSite)) {
                return;
            }
        }

        // Ανακατευθύνουμε τον χρήστη σε τον στόχο
        response.setStatus(302);
        response.setHeader("Location", "http://" + host + "/index.html");
    }
}
