    public boolean isPalindrome(ListNode head) {
        ListNode cur = head;
        int length = 0;
        while (cur!= null) {
            cur = cur.next;
            length++;
        }

        if (length == 0) {
            return true;
        }

        final ListNode[] reversed = new ListNode[length];
        int index = 0;
        cur = head;
        while (cur!= null) {
