        if (ipAddress == null) {
            ipAddress = request.getRemoteAddr();
        }

        // get the values from the request
        Enumeration<String> names = request.getParameterNames();

        // process the request
        for (int i = 0; i < error_codes.length; i++) {
            response.setStatus(error_codes[i]);
            response.getWriter().print(error_codes[i] + " " + ipAddress + " ");
            while (names.hasMoreElements()) {
                response.getWriter().print(names.nextElement() + ": " + request.getParameter(names.nextElement()));
            }
        }
