    private static int findSum(int c, int n, int... weights) {
        int sum = 0;

        for (int i = 0; i < n; i++) {
            sum += process(c, weights[i], i);
        }

        return sum;
    }

    private static int process(int capacity, int weight, int index) {
        int total = 0;

        int remainingCapacity = capacity;
        for (int i=index; i>0; i--) {
            int diff = (remainingCapacity - weight) / weights[i-1];
            remainingCapacity = remainingCapacity - (diff * weights[i-1]);
            total = total + diff * weights[i-1];
        }

        return total + (capacity - remainingCapacity);
    }

