import java.net.URI;
import java.net.URISyntaxException;
import java.util.Arrays;

import org.jsoup.Jsoup;
import org.jsoup.nodes.Document;
import org.jsoup.nodes.Element;
import org.jsoup.select.Elements;

public class Main {
    public static void main(String[] args) {
        assert args.length > 0;

        String file = args[0];
        String url = args[1];

        if (!validURL(url)) {
            System.out.println("Invalid URL specified");
            System.exit(1);
        }

        try {
            Document doc = Jsoup.connect(url).get();

            System.out.println("<editor id=\"editor\">");
            System.out.print("<code id=\"code\">");

            for (Element codeElement : doc.getElementsByTag("code")) {
                if (!codeElement.attr("id").equals("code")) {
                    continue;
                }

                Elements lines = codeElement.getElementsByTag("pre");
                String[] lineArray = new String[lines.size()];

                for (int i = 0; i < lines.size(); i++) {
                    lineArray[i] = lines.get(i).text();
                }

                System.out.println(Arrays.toString(lineArray).replace("[", "").replace("]", "").replace("\"", "").replace("\n", "\\n"));
            }

            System.out.println("</code>");
            System.out.println("</editor>");
            System.out.println();

        } catch (Exception e) {
            e.printStackTrace();
        }
    }

    private static boolean validURL(String url) {
        try {
            new URI(url);
        } catch (URISyntaxException e) {
            return false;
        }
        return true;
    }
}
