package com.example;

import java.lang.invoke.MethodHandle;
import java.lang.invoke.MethodHandles;
import java.lang.invoke.MethodType;
import java.lang.reflect.Method;

public class Demo {

    public static void main(String[] args) throws Throwable {
        // #method-handle
        MethodType methodType = MethodType.methodType(String.class, String.class, String.class);
        String string = "Hello!";
        MethodHandles.Lookup lookup = MethodHandles.lookup();
        MethodHandle methodHandle = lookup.findVirtual(String.class, "concat", methodType);
        String result = (String) methodHandle.invokeWithArguments(string, "World");
        // #end-method-handle

        // #method-reference
        String result2 = "Hello!".concat("World");
        // #end-method-reference

        // #method-invocation
        Method method = String.class.getMethod("concat", String.class);
        String result3 = (String) method.invoke(string, "World");
        // #end-method-invocation

        System.out.println(result);
        System.out.println(result2);
        System.out.println(result3);
    }

}
