public class SolutionServlet extends HttpServlet {
    private final ObjectMapper mapper = new ObjectMapper();

    @Override
    protected void doPost(HttpServletRequest request, HttpServletResponse response) throws ServletException, IOException {
        int assignmentId = Integer.parseInt(request.getParameter("assignmentId"));
        AssignmentRepository repository = AssignmentRepository.getInstance();
        Assignment assignment = repository.get(assignmentId);
        String code = request.getParameter("code");
        boolean passed = assignment.check(code);
        if (passed) {
            printJson(response.getWriter(), assignment.getId(), passed, new SolutionResult(true, new ArrayList<>()));
        } else {
            printJson(response.getWriter(), assignment.getId(), passed, new SolutionResult(false, assignment.getErrors()));
        }
    }

    private void printJson(PrintWriter writer, int assignmentId, boolean passed, SolutionResult result) throws IOException {
        ObjectNode answer = mapper.createObjectNode();
        answer.put("passed", passed);
        answer.put("assignmentId", assignmentId);
        ArrayNode errors = answer.putArray("errors");
        if (result.hasErrors()) {
            for (String message : result.getErrors()) {
                errors.add(message);
            }
        }
        writer.print(answer.toString());
    }

    private class SolutionResult {
        private boolean passed;
        private List<String> errors;

        public SolutionResult(boolean passed, List<String> errors) {
            this.passed = passed;
            this.errors = errors;
        }

        public boolean hasErrors() {
            return this.errors!= null && this.errors.size() > 0;
        }

        public List<String> getErrors() {
            return this.errors;
        }
    }

