package compiler.model.AbstractSyntaxTree;

import compiler.model.SymbolTree.Symbol;

import java.util.HashMap;
import java.util.Map;

/**
 * Abstrakte Grammatikstuktur. Implementierung durch alle Klassen, die einen AST-Knoten repraesentieren
 * <p>
 * Bezeichnung: Nicht-Terminal symbol
 *
 * @param <E> Typenparameter fuer Typen, die von der Klasse implementiert werden
 */
abstract class AstNode<E extends Type<E>> {

    private final Map<String, E> children = new HashMap<>();
    private E type;

    /**
     * Erzeugt einen neuen AST-Knoten.
     *
     * @param type Typenparameter fuer Typen, die von der Klasse implementiert werden
     */
    public AstNode(E type) {
        this.type = type;
    }

    /**
     * Registriert einen Kind-Knoten.
     *
     * @param child Name des Knotens
     * @param node  Kind-Knoten
     */
    public void addChild(String child, E node) {
        children.put(child, node);
    }

    /**
     * Liefert einen Kind-Knoten.
     *
     * @param name Name des Knotens
     * @return Kind-Knoten
     */
    public E getChild(String name) {
        return children.get(name);
    }

    /**
     * Liefert den Typenparameter.
     *
     * @return Typenparameter
     */
    public E getType() {
        return type;
    }

    /**
     * Erzeugt einen Kopie des AST-Knotens.
     *
     * @return Kopie des AST-Knotens
     */
    public abstract AstNode<E> copy();
}
